-- Queryopsy case database: Payroll Leak
-- Source: data/samples/payroll_placeholder.csv (PLACEHOLDER - synthetic)
-- Generated by pipeline/build.py - do not edit by hand.

-- Department master.
CREATE TABLE departments (
  department TEXT PRIMARY KEY,
  cost_centre TEXT
);

-- Employee master (source HR data + a synthetic bank account per employee).
CREATE TABLE employees (
  emp_id INTEGER PRIMARY KEY,
  age INTEGER,
  department TEXT REFERENCES departments(department),
  job_role TEXT,
  job_level INTEGER,
  monthly_income INTEGER,
  overtime INTEGER,
  hire_date TEXT,
  exit_date TEXT,
  bank_account TEXT
);

-- Monthly salary payments (derived from monthly_income for this case).
CREATE TABLE payroll (
  pay_id INTEGER PRIMARY KEY,
  emp_id INTEGER REFERENCES employees(emp_id),
  pay_month TEXT,
  net_pay REAL,
  paid_on TEXT
);

